            Hash256 codeHash = DecodeCodeHash(rlpStream);

            return (codeHash, storageRoot);
        }

        public (Hash256 CodeHash, Hash256 StorageRoot) DecodeHashesOnly(ref Rlp.ValueDecoderContext context)
        {
            context.SkipLength();
            context.SkipItem();
            context.SkipItem();

